          "body": "Au lieu de lignes préenregistrées, CASH NOIR modélise la psychologie des PNJ par les mathématiques. Chaque interaction évalue tes propos en temps réel via trois jauges scalaires interconnectées : Peur, Colère et Suspicion. Intimider un receleur peut faire grimper sa Peur et baisser temporairement ses prétentions, mais si tu vas trop loin, sa Suspicion provoquera une rupture immédiate. Insulter un vendeur avec une offre dérisoire déclenchera un pic de Colère qui verrouillera définitivement son prix plancher.\n\nCes métriques n'opèrent pas en vase clos. Elles interagissent avec une valeur de réserve cachée sous laquelle le vendeur ne descendra jamais. Le système analyse en continu le ton, l'intention sémantique, le rapport de force et le contexte économique. Pour comprendre comment ces variables se résolvent après chaque échange, consulte notre [autopsie déterministe d'un deal et psychologie de négociation](/blog/deterministic-deal-autopsy-negotiation-psychology). Si un passeur soupçonne que tu portes un micro, aucune flatterie ne sauvera la transaction : tu dois lire son langage corporel et réajuster ton approche avant qu'il ne claque la porte."
