          "body": "Persuader exige un vrai levier, pas de simples statistiques de charisme. Dans CASH NOIR, ce levier s'obtient par l'observation médico-légale et le renseignement progressif. Tu disposes d'outils concrets sur ton comptoir — la Loupe, la lampe UV et le scanner radio de la police — pour déceler défauts, taches de sang, numéros de série meulés ou patrouilles en cours avant même d'ouvrir la bouche.\n\nAcculer un vendeur avec une preuve matérielle irréfutable inflige un choc psychologique ciblé qu'aucune option de dialogue préécrite ne peut égaler. Tu peux analyser ces dynamiques d'interrogatoire dans notre dossier sur les [meilleurs jeux d'interrogatoire IA et systèmes PNJ](/blog/best-ai-interrogation-npc-games). Quand tu détectes un faux poinçon sous lampe UV tout en mentionnant une alerte de patrouille interceptée à la radio, la Suspicion du vendeur chute tandis que sa Peur s'envole, faisant basculer la négociation en ta faveur sans risquer le clash."
