          "heading": "Dossiers progressifs au fil des factions",
          "body": "Les PNJ statiques oublient tout d'une scène à l'autre ; pas les figures de la pègre. CASH NOIR met en scène 100 personnages répartis dans 10 factions criminelles, mêlant 20 personnalités écrites sur mesure à 80 variations procédurales. Au fil de leurs passages dans ta boutique, des dossiers progressifs révèlent leurs failles intimes : un Secret au 2e passage, un Point Faible au 3e et une Ligne Rouge critique au 4e.\n\nCe système transforme chaque troc ponctuel en une véritable campagne narrative. Exploiter l'addiction ou la dette d'un trafiquant d'armes marche une fois, mais abuser de cet avantage sur plusieurs rencontres peut t'aliéner son syndicat à jamais. Pour gérer ces équilibres précaires, plonge dans le [guide du dossier Boris Kovalenko saison 1](/guides/boris-kovalenko-season-1-dossier) pour voir comment mémoire dynamique, allégeances et ultimatums scellent ta survie à long terme."
