          "heading": "Risque émergent contre filets de sécurité scriptés",
          "body": "Les systèmes traditionnels protègent le joueur de l'échec cuisant afin de préserver les rails de l'histoire. Dans CASH NOIR, négocier librement comporte une finalité typique du roguelike. Pousse un contrebandier armé à bout, et il partira en boycottant ta boutique auprès de sa faction ou en balançant ton adresse au commissariat pour faire flamber ton Heat.\n\nChaque contre-proposition entame tes marges face au loyer quotidien et aux dîmes du cartel. Mal évaluer l'état psychologique d'un client peut te contraindre à une braderie d'urgence fatale pour tes [runs de survie en Ascension I à X](/guides/ascension-i-to-x-survival-guide). En éliminant les barrières narratives factices et en t'obligeant à trouver tes propres arguments, le moteur d'émotions réintroduit une tension authentique dans le genre : l'avenir du dialogue appartient à la simulation psychologique émergente."
