      "excerpt": "Los árboles de diálogo rompen la inmersión. Descubre cómo CASH NOIR cambia opciones estáticas por simulación psicológica y emocional en tiempo real.",
      "directAnswer": "Los árboles de diálogo estáticos A/B/C eliminan el riesgo real al convertir las conversaciones en mero reconocimiento de patrones predecibles. CASH NOIR sustituye los guiones ramificados por un motor emocional no guionizado que rastrea tres medidores psicológicos en tiempo real —Miedo, Ira y Sospecha— frente a precios mínimos ocultos y expedientes de facción procedimentales, obligándote a negociar con naturalidad mediante lenguaje natural dinámico.",
