          "heading": "L'architecture mathématique de la difficulté cumulative",
          "body": "La difficulté roguelike dérive souvent vers un vulgaire gonflement de stats. Dans CASH NOIR, la tension grimpe par friction structurelle plutôt que par des barres de PV arbitraires. Sur les 10 paliers d'Ascension cumulatifs, chaque variable du moteur de négociation se resserre : la Colère des vendeurs retombe plus lentement, la Suspicion explose au moindre lowball agressif et les loyers de minuit augmentent de manière exponentielle. Pour garantir que l'Ascension X reste accessible sans dépendre d'une seed RNG miracle, nous avons conçu un banc d'essai Monte-Carlo automatisé. Nous avons lancé 300 campagnes complètes de 40 jours avec des styles de jeu déterministes, du lowball ultra-conservateur au blanchiment à haut risque sur le marché noir. La simulation a démontré que les tactiques de base s'effondrent dès le Jour 12 sans une maîtrise totale du [guide de survie Ascension I à X](/guides/ascension-i-to-x-survival-guide)."
