          "heading": "Le dilemme du Coffre-fort sous règles hardcore maximales",
          "body": "L'épreuve ultime de notre banc Monte-Carlo portait sur les objets d'histoire. Conserver les artefacts narratifs clés dans le Coffre-fort de la boutique te rapporte une prime de fin de partie massive de $7,500 et une chute immédiate de Heat, mais immobilise un capital vital pour tes opérations courantes. En Ascension X, stocker des objets comme Container 47 impose une tension financière insoutenable quand le percepteur frappe à minuit. Tu dois constamment arbitrer entre allégeance à long terme envers une faction et survie immédiate. Tu peux tester ces dilemmes tactiques au millimètre dès maintenant en lançant une session sur [/play](/play) ou en relevant le défi quotidien de la communauté via [/play/daily](/play/daily)."
