          "heading": "La arquitectura matemática de la dificultad acumulativa",
          "body": "La dificultad en los roguelikes suele caer en el inflado artificial de estadísticas. En CASH NOIR, la dificultad escala mediante fricción estructural, no con barras de vida arbitrarias. A lo largo de 10 niveles acumulativos de Ascension, cada variable del motor de negociación se vuelve más hostil: el Anger del vendedor se disipa más lento, la Suspicion se dispara con ofertas agresivas a la baja y el alquiler de medianoche se acumula de forma exponencial. Para garantizar que Ascension X fuera superable sin depender de pura suerte de RNG, creamos un entorno de pruebas Monte-Carlo headless. Ejecutamos 300 campañas completas de 40 días con estilos de juego deterministas, desde el regateo ultraconservador hasta el blanqueo de alto riesgo en el mercado negro. La simulación demostró que las tácticas básicas de negociación fracasan hacia el Día 12 sin un dominio profundo de la [guía de supervivencia de Ascension I a X](/guides/ascension-i-to-x-survival-guide)."
