      "metaDesc": "Desarma a Boris Kovalenko en Cash Noir T1. Desbloquea su dossier, neutraliza su contraoferta del +12% y supera Container 47. Domínalo en CASH NOIR.",
      "directAnswer": "Boris Kovalenko es el vendedor insignia de la Temporada 1 de Cash Noir: un exmecánico de cargamentos fantasma de Odesa con una contraoferta pasiva del +12% y el peligroso ultimátum de Container 47. Vencer su modelo de negociación exige desbloquear su dossier a lo largo de cuatro encuentros, explotar su umbral de Miedo con datos logísticos portuarios implacables y respetar su Línea Roja irreversible.",
