      "title": "Arbitrage nocturne : Vente Rapide vs Enchères Clandestines",
      "metaDesc": "Domine l'arbitrage nocturne dans CASH NOIR. Vente Rapide illimitée à -5% Heat ou Enchères Clandestines à fort rendement : calcule bien ton blanchiment.",
      "directAnswer": "Survivre à l'arbitrage nocturne dans CASH NOIR exige d'équilibrer la liquidation du stock brûlant et l'accumulation de Heat. La Vente Rapide permet d'écouler sans limite tout en purgeant 5% de Heat par objet, idéal pour esquiver la pression policière. Les Enchères Clandestines offrent une prime de valorisation de +20% une fois par nuit, mais imposent soit -$250 de frais de blanchiment, soit +18% de Heat, les lots suivants subissant une pénalité de saturation du marché de -25%.",
