          "q": "Puis-je utiliser la Vente Rapide plusieurs fois en une seule nuit ?",
          "a": "Oui. La Vente Rapide n'a aucune limite de volume, ce qui te permet de liquider plusieurs objets à la suite pour purger 5% de Heat par item et générer du capital opérationnel immédiat avant minuit."
