      "title": "Arbitraje nocturno: Venta rápida vs. Subasta clandestina",
      "metaDesc": "Domina el arbitraje nocturno en Cash Noir. Compara la Venta rápida a -5% de Heat frente a Subastas clandestinas rentables y su matemática de blanqueo.",
      "directAnswer": "El arbitraje nocturno en Cash Noir consiste en equilibrar la liquidación de mercancía caliente frente a las penalizaciones acumuladas de Heat. La Venta rápida permite descargas ilimitadas y limpia un 5% de Heat por objeto, ideal para aguantar la presión policial. Las Subastas clandestinas ofrecen una prima del +20% sobre la tasación una vez por noche, pero exigen pagar una tasa de limpieza de -$250 o asumir un +18% de Heat, sufriendo los lotes posteriores una penalización de saturación del -25%.",
